import { deleteConfig } from "@/api/cmdb/ciConfig";
export default {
  props: ['isShow', "configId"],
  data: function data() {
    return {
      description: '',
      saveLoading: false
    };
  },
  mounted: function mounted() {},
  methods: {
    // 删除并提交
    delConfig: function delConfig(val) {
      var _this = this;
      var form = {
        id: this.configId,
        description: this.description,
        needCommit: val
      };
      this.saveLoading = true;
      deleteConfig(form).then(function (res) {
        _this.$message({
          type: 'success',
          message: '保存成功！'
        });
        _this.saveLoading = false;
        _this.$emit('submitDelConfig');
      }).catch(function () {
        _this.saveLoading = false;
      });
    }
  }
};
